    mint = await createMint(provider.connection, owner, owner.publicKey, null, 0);
    // vault's token account (PDA owner, off curve) + fund it with 1000 tokens
    const vAtaAcc = await getOrCreateAssociatedTokenAccount(provider.connection, owner, mint, vault, true);
